import { AlchemystAI } from '@alchemystai/sdk';
import { generateText } from 'ai';
import { openai } from '@ai-sdk/openai';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';

async function main() {
  const ALCHEMYST_AI_API_KEY = process.env.ALCHEMYST_AI_API_KEY;
  const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
  const ZEALT_RUN_ID = process.env.ZEALT_RUN_ID || `local-${Date.now()}`;

  if (!ALCHEMYST_AI_API_KEY || !OPENAI_API_KEY) {
    console.error('Missing required environment variables: ALCHEMYST_AI_API_KEY or OPENAI_API_KEY');
    process.exit(1);
  }

  const userId = `user-${ZEALT_RUN_ID}`;
  const sessionId = `ticket-${ZEALT_RUN_ID}-${Math.random().toString(36).substring(7)}`;

  const client = new AlchemystAI({ apiKey: ALCHEMYST_AI_API_KEY });

  // Day 1: Customer reports issue
  const day1Text = `Customer reporting: My order #12345 has not arrived yet. Can you please check the status?`;
  console.log('Day 1: Storing customer message...');
  await client.v1.context.memory.add({
    sessionId,
    userId,
    contents: [{ content: day1Text }]
  });

  // Day 2: Support agent update
  const day2Text = `Support Agent note: We have investigated the issue for order #12345. It appears there is a shipping carrier delay due to weather conditions. We are monitoring the situation.`;
  console.log('Day 2: Storing support agent update...');
  await client.v1.context.memory.add({
    sessionId,
    userId,
    contents: [{ content: day2Text }]
  });

  // Day 3: Customer asks for update
  console.log('Day 3: Searching for memories...');
  let memories: any[] = [];
  let retries = 5;
  while (retries > 0) {
    const searchResponse = await client.v1.context.memory.search({
      sessionId,
      userId,
      query: 'order status #12345',
      limit: 10
    });

    // Check if both memories are indexed
    // Alchemyst search returns memories in a specific format, we need to extract the content
    memories = searchResponse.memories || [];
    console.log(`Found ${memories.length} memories. Retries left: ${retries - 1}`);

    const foundDay1 = memories.some(m => m.content.includes('order #12345'));
    const foundDay2 = memories.some(m => m.content.includes('shipping carrier delay'));

    if (foundDay1 && foundDay2) {
      break;
    }

    retries--;
    if (retries > 0) {
      await new Promise(resolve => setTimeout(resolve, 5000)); // Wait 5 seconds before retry
    }
  }

  if (memories.length === 0) {
    console.error('Failed to retrieve memories after retries.');
    process.exit(1);
  }

  const context = memories.map(m => m.content).join('\n---\n');
  const userPrompt = 'What is the status of my order?';

  console.log('Day 3: Generating LLM response...');
  const { text: summary } = await generateText({
    model: openai('gpt-4o-mini'),
    prompt: `You are a helpful customer support assistant. Use the following ticket history to answer the customer's question.

Ticket History:
${context}

Customer: ${userPrompt}
Assistant:`,
    temperature: 0,
  });

  console.log('Summary generated:', summary);

  // Validation
  const hasOrderNumber = summary.includes('12345');
  const hasShippingCarrier = summary.includes('shipping carrier');

  if (!hasOrderNumber || !hasShippingCarrier) {
    console.error('Validation failed: Summary does not contain required substrings "12345" and "shipping carrier".');
    console.error('Summary was:', summary);
    process.exit(1);
  }

  // Write outputs
  const summaryPath = '/workspace/summary.txt';
  const logPath = '/workspace/run.log';

  await fs.writeFile(summaryPath, summary, 'utf-8');

  const logData = {
    runId: ZEALT_RUN_ID,
    userId,
    sessionId,
    day1Stored: day1Text,
    day2Stored: day2Text,
    memoriesFound: memories.length,
    summaryPath
  };

  await fs.writeFile(logPath, JSON.stringify(logData, null, 2), 'utf-8');

  console.log('Run completed successfully.');
}

main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
